responseSchema:
{
  "status": {
    "type": "string",
    "description": "Indicates whether the request was successful (e.g., 'success', 'error')"
  },
  "data": {
    "type": "object",
    "description": "Main payload returned by the API",
    "properties": {
      "userId": {
        "type": "string",
        "description": "Unique identifier of the user"
      },
      "records": {
        "type": "array",
        "description": "List of returned records",
        "items": {
          "type": "object",
          "properties": {
            "recordId": {
              "type": "string",
              "description": "Unique identifier for the record"
            },
            "value": {
              "type": "number",
              "description": "Numeric value associated with the record"
            }
          }
        }
      }
    }
  },
  "error": {
    "type": "object",
    "description": "Error details when status = 'error'",
    "properties": {
      "code": {
        "type": "string",
        "description": "Machine-readable error code"
      },
      "message": {
        "type": "string",
        "description": "Human-readable error message"
      }
    }
  }
}
